class CreateTeacherUseCase {
  private teacherRepository: any;

  constructor(teacherRepository: any) {
    this.teacherRepository = teacherRepository;
  }

  async execute(data) {
    const {
      // User fields
      fullNameEn, fullNameLo, email, phoneNumber,
      // Teacher fields (employeeCode is generated by the repository)
      gender, specialization, qualification,
      hireDate, salary, bankName, bankAccountName, bankAccountNumber,
      provinceId, districtId, village, address, notes,
    } = data;

    // No password: the teacher can't sign in until an account is opened on the Users page.
    const userData = {
      fullNameEn, fullNameLo,
      ...(email ? { email } : {}),
      ...(phoneNumber ? { phoneNumber } : {}),
      passwordHash: null,
      isActive: true,
    };

    const teacherData = {
      ...(gender ? { gender } : {}),
      ...(specialization !== undefined ? { specialization } : {}),
      ...(qualification !== undefined ? { qualification } : {}),
      ...(hireDate ? { hireDate: new Date(hireDate) } : {}),
      ...(salary !== undefined && salary !== null ? { salary } : {}),
      ...(bankName ? { bankName } : {}),
      ...(bankAccountName ? { bankAccountName } : {}),
      ...(bankAccountNumber ? { bankAccountNumber } : {}),
      ...(provinceId !== undefined ? { provinceId } : {}),
      ...(districtId !== undefined ? { districtId } : {}),
      ...(village !== undefined ? { village } : {}),
      ...(address !== undefined ? { address } : {}),
      ...(notes !== undefined ? { notes } : {}),
    };

    return this.teacherRepository.create(userData, teacherData);
  }
}

export default CreateTeacherUseCase;
